-- ============================================================================================
-- DADOS DE DEMONSTRAÇÃO — SOMENTE DESENVOLVIMENTO LOCAL. GERADO por scripts/gen-seed.mjs. NÃO edite à mão.
-- Executado automaticamente por `supabase db reset` (nunca no Supabase hospedado, a menos que você rode este arquivo
-- manualmente: NÃO faça isso em produção). Tudo aqui é FICTÍCIO e determinístico (sem random()): rodar de novo gera sempre os
-- mesmos dados. Para remover: apague a organização «Empresa Demonstração» (as tabelas em cascata limpam o resto) ou rode `supabase db reset`.
-- Os formulários, o modelo de score e as notas usam as MESMAS funções do sistema (validação e pontuação no banco);
-- só as datas são recuadas para o painel mostrar histórico. Os e-mails usam o domínio reservado .invalid (nunca existem).
--
-- Usuários de demonstração (senha local única: DemoLocal#2026):
--   dono@demo.exemplo       proprietário  (exige cadastrar verificação em duas etapas no primeiro acesso)
--   gerente@demo.exemplo    gestor comercial (vê todos os leads, formulários, modelo e distribuição)
--   vendedor1@demo.exemplo  vendedor      (vê só os leads atribuídos a ele)
--   vendedor2@demo.exemplo  vendedor
--   leitor@demo.exemplo     leitor        (somente leitura)
-- Formulário público de demonstração: /f/qualificacao-b2b, /f/busca-de-imovel, /f/agencia-de-marketing
-- ============================================================================================

create function pg_temp.d(p_days_ago int, p_time time default '12:00') returns timestamptz language sql stable as $$
  select (((now() at time zone 'America/Sao_Paulo')::date - p_days_ago)::timestamp + p_time) at time zone 'America/Sao_Paulo'
$$;

-- Só no seed: desliga/religa os gatilhos de regra (dono das tabelas pode; o papel postgres do Supabase não é superusuário).
create function pg_temp.triggers(p_on boolean) returns void language plpgsql as $f$
declare t text;
begin
  foreach t in array array['leads', 'lead_activities', 'lead_forms', 'lead_form_versions', 'scoring_models', 'scoring_rules', 'campaigns', 'lead_settings', 'distribution_rules'] loop
    execute format('alter table public.%I %s trigger user', t, case when p_on then 'enable' else 'disable' end);
  end loop;
end $f$;

create temp table seed_rows (
  i int, form_key text, name text, email text, phone text, company text, segment text, answers jsonb, source text, medium text, campaign text,
  created_ago int, created_hour int, plan text, contact_min int, seller int, reason text, follow_days int, dup_of int
) on commit drop;

do $$
declare
  org uuid := 'e5e5e5e5-0000-4000-8000-000000000001';
  model uuid := 'e5e5e5e5-0000-4000-8000-0000000000d1';
  u_dono uuid := 'e5e5e5e5-0000-4000-8000-0000000000a1';
  u_ger uuid := 'e5e5e5e5-0000-4000-8000-0000000000a2';
  u_v1 uuid := 'e5e5e5e5-0000-4000-8000-0000000000a3';
  u_v2 uuid := 'e5e5e5e5-0000-4000-8000-0000000000a4';
  u_leitor uuid := 'e5e5e5e5-0000-4000-8000-0000000000a5';
  pw text := extensions.crypt('DemoLocal#2026', extensions.gen_salt('bf'));
  r record; v_form uuid; v_ver uuid; v_schema jsonb; v_logic jsonb; chk jsonb; res jsonb; v_rules jsonb; v_lead uuid; v_sub uuid; v_camp uuid;
  v_status public.lead_status; v_created timestamptz; v_contact timestamptz; v_assignee uuid; v_dup uuid; cls text; sc int;
  v_thr jsonb := '{"warm_min":40,"hot_min":70,"qualified_min":70}';
begin
  if exists (select 1 from public.organizations where id = org) then
    return; -- já semeado
  end if;

  -- ---------------------------------------------------------------- usuários (login por e-mail e senha)
  select '00000000-0000-0000-0000-000000000000', v.id, 'authenticated', 'authenticated', v.email, pw, now(),
         '{"provider":"email","providers":["email"]}'::jsonb, jsonb_build_object('full_name', v.nome), now(), now(), '', '', '', ''
  from (values (u_dono, 'dono@demo.exemplo', 'Marina Proprietária'), (u_ger, 'gerente@demo.exemplo', 'Rafael Gestor'),
               (u_v1, 'vendedor1@demo.exemplo', 'Camila Vendas'), (u_v2, 'vendedor2@demo.exemplo', 'Diego Vendas'),
               (u_leitor, 'leitor@demo.exemplo', 'Lívia Leitora')) as v(id, email, nome);
  select gen_random_uuid(), u.id, u.email, jsonb_build_object('sub', u.id::text, 'email', u.email, 'email_verified', true), 'email', now(), now(), now()
  from auth.users u where u.id in (u_dono, u_ger, u_v1, u_v2, u_leitor);
  update public.profiles p set full_name = u.raw_user_meta_data ->> 'full_name' from auth.users u where u.id = p.id and u.id in (u_dono, u_ger, u_v1, u_v2, u_leitor);

  -- ---------------------------------------------------------------- organização (configuração e motivos nascem por gatilho)

  perform pg_temp.triggers(false);
  update public.lead_settings set assignment_strategy = 'round_robin', privacy_policy_url = 'https://exemplo-demo.invalid/privacidade' where organization_id = org;
  update public.lead_settings set rr_last_user = u_v2 where organization_id = org;


  -- ---------------------------------------------------------------- formulários (versão 1 publicada; o 4º segue como rascunho)
  values ('e5e5e5e5-0000-4000-8000-00000000f001', org, 'Qualificação B2B', 'qualificacao-b2b', 'Empresa, porte, orçamento, prazo e poder de decisão — para vendas consultivas.', 'published', 'Obrigado! Recebemos suas informações e entraremos em contato.', pg_temp.d(112));
  values ('e5e5e5e5-0000-4000-8000-00000000e001', org, 'e5e5e5e5-0000-4000-8000-00000000f001', 1, '{"steps":[{"id":"contato","title":"Seus dados"},{"id":"empresa","title":"Sua empresa"},{"id":"projeto","title":"Seu projeto"}],"fields":[{"key":"nome","type":"text","label":"Nome completo","required":true,"lead_field":"name","step":"contato"},{"key":"email","type":"email","label":"E-mail profissional","required":true,"lead_field":"email","step":"contato"},{"key":"telefone","type":"phone","label":"Telefone / WhatsApp","required":false,"lead_field":"phone","step":"contato"},{"key":"empresa","type":"text","label":"Empresa","required":true,"lead_field":"company_name","step":"contato"},{"key":"cargo","type":"select","label":"Qual é o seu papel na decisão?","required":true,"step":"empresa","options":[{"value":"decisor","label":"Decido a contratação"},{"value":"influenciador","label":"Influencio a decisão"},{"value":"pesquisa","label":"Estou pesquisando para outra pessoa"}]},{"key":"funcionarios","type":"select","label":"Quantos funcionários a empresa tem?","required":true,"step":"empresa","options":[{"value":"ate_10","label":"Até 10"},{"value":"11_50","label":"11 a 50"},{"value":"51_200","label":"51 a 200"},{"value":"mais_200","label":"Mais de 200"}]},{"key":"segmento","type":"text","label":"Segmento de atuação","required":false,"lead_field":"segment","step":"empresa","max_length":120},{"key":"orcamento","type":"select","label":"Qual o orçamento previsto?","required":true,"step":"projeto","options":[{"value":"ate_5k","label":"Até R$ 5 mil"},{"value":"5k_20k","label":"R$ 5 mil a R$ 20 mil"},{"value":"20k_50k","label":"R$ 20 mil a R$ 50 mil"},{"value":"mais_50k","label":"Acima de R$ 50 mil"},{"value":"indefinido","label":"Ainda não definido"}]},{"key":"prazo","type":"select","label":"Quando pretende contratar?","required":true,"step":"projeto","options":[{"value":"ate_30","label":"Em até 30 dias"},{"value":"30_90","label":"Entre 30 e 90 dias"},{"value":"mais_90","label":"Em mais de 90 dias"},{"value":"pesquisando","label":"Só pesquisando"}]},{"key":"problema","type":"textarea","label":"Qual problema você quer resolver?","required":false,"step":"projeto","max_length":1000,"help":"Quanto mais detalhes, melhor o atendimento."}]}'::jsonb, '[]'::jsonb, '{"required":true,"text":"Concordo em compartilhar meus dados para que a empresa entre em contato comigo sobre esta solicitação, conforme a política de privacidade."}'::jsonb, pg_temp.d(110), pg_temp.d(112));
  update public.lead_forms set current_published_version_id = 'e5e5e5e5-0000-4000-8000-00000000e001' where id = 'e5e5e5e5-0000-4000-8000-00000000f001';
  values ('e5e5e5e5-0000-4000-8000-00000000f002', org, 'Busca de imóvel', 'busca-de-imovel', 'Interesse, tipo de imóvel, faixa de valor, prazo e financiamento (com pergunta condicional).', 'published', 'Obrigado! Recebemos suas informações e entraremos em contato.', pg_temp.d(112));
  values ('e5e5e5e5-0000-4000-8000-00000000e002', org, 'e5e5e5e5-0000-4000-8000-00000000f002', 1, '{"steps":[{"id":"contato","title":"Seus dados"},{"id":"imovel","title":"O imóvel"}],"fields":[{"key":"nome","type":"text","label":"Nome completo","required":true,"lead_field":"name","step":"contato"},{"key":"email","type":"email","label":"E-mail profissional","required":true,"lead_field":"email","step":"contato"},{"key":"telefone","type":"phone","label":"Telefone / WhatsApp","required":false,"lead_field":"phone","step":"contato"},{"key":"interesse","type":"radio","label":"O que você procura?","required":true,"step":"imovel","options":[{"value":"comprar","label":"Comprar"},{"value":"alugar","label":"Alugar"},{"value":"investir","label":"Investir"}]},{"key":"tipo","type":"multiselect","label":"Tipo de imóvel","required":true,"step":"imovel","options":[{"value":"apartamento","label":"Apartamento"},{"value":"casa","label":"Casa"},{"value":"terreno","label":"Terreno"},{"value":"comercial","label":"Sala / loja"}]},{"key":"valor","type":"select","label":"Faixa de valor","required":true,"step":"imovel","options":[{"value":"ate_300k","label":"Até R$ 300 mil"},{"value":"300k_700k","label":"R$ 300 mil a R$ 700 mil"},{"value":"700k_1500k","label":"R$ 700 mil a R$ 1,5 milhão"},{"value":"mais_1500k","label":"Acima de R$ 1,5 milhão"}]},{"key":"prazo","type":"select","label":"Em quanto tempo quer fechar?","required":true,"step":"imovel","options":[{"value":"ate_30","label":"Em até 30 dias"},{"value":"30_90","label":"Entre 30 e 90 dias"},{"value":"mais_90","label":"Mais de 90 dias"}]},{"key":"financia","type":"checkbox","label":"Vou precisar de financiamento","required":false,"step":"imovel"},{"key":"entrada","type":"currency","label":"Quanto tem para a entrada (R$)?","required":false,"step":"imovel","min":0},{"key":"visita","type":"checkbox","label":"Quero agendar uma visita","required":false,"step":"imovel"}]}'::jsonb, '[{"target":"entrada","show_if":{"all":[{"field":"financia","op":"is_true"}]}}]'::jsonb, '{"required":true,"text":"Concordo em compartilhar meus dados para que a empresa entre em contato comigo sobre esta solicitação, conforme a política de privacidade."}'::jsonb, pg_temp.d(110), pg_temp.d(112));
  update public.lead_forms set current_published_version_id = 'e5e5e5e5-0000-4000-8000-00000000e002' where id = 'e5e5e5e5-0000-4000-8000-00000000f002';
  values ('e5e5e5e5-0000-4000-8000-00000000f003', org, 'Contato para agência de marketing', 'agencia-de-marketing', 'Investimento mensal, objetivos, canais atuais e site — para captar clientes de marketing.', 'published', 'Obrigado! Recebemos suas informações e entraremos em contato.', pg_temp.d(112));
  values ('e5e5e5e5-0000-4000-8000-00000000e003', org, 'e5e5e5e5-0000-4000-8000-00000000f003', 1, '{"steps":[{"id":"contato","title":"Seus dados"},{"id":"marketing","title":"Marketing atual"}],"fields":[{"key":"nome","type":"text","label":"Nome completo","required":true,"lead_field":"name","step":"contato"},{"key":"email","type":"email","label":"E-mail profissional","required":true,"lead_field":"email","step":"contato"},{"key":"telefone","type":"phone","label":"Telefone / WhatsApp","required":false,"lead_field":"phone","step":"contato"},{"key":"empresa","type":"text","label":"Empresa","required":true,"lead_field":"company_name","step":"contato"},{"key":"site","type":"text","label":"Endereço do site ou Instagram","required":false,"step":"marketing","max_length":200},{"key":"investimento","type":"select","label":"Quanto investe por mês em marketing?","required":true,"step":"marketing","options":[{"value":"nenhum","label":"Nada ainda"},{"value":"ate_2k","label":"Até R$ 2 mil"},{"value":"2k_10k","label":"R$ 2 mil a R$ 10 mil"},{"value":"mais_10k","label":"Acima de R$ 10 mil"}]},{"key":"objetivos","type":"multiselect","label":"O que quer alcançar?","required":true,"step":"marketing","options":[{"value":"leads","label":"Gerar leads"},{"value":"marca","label":"Fortalecer a marca"},{"value":"vendas","label":"Vender online"},{"value":"retencao","label":"Reter clientes"}]},{"key":"canais","type":"multiselect","label":"Canais que já usa","required":false,"step":"marketing","options":[{"value":"google","label":"Google Ads"},{"value":"meta","label":"Instagram / Facebook"},{"value":"email","label":"E-mail marketing"},{"value":"seo","label":"SEO / blog"}]},{"key":"prazo","type":"select","label":"Quando quer começar?","required":true,"step":"marketing","options":[{"value":"imediato","label":"Imediatamente"},{"value":"mes","label":"Neste mês"},{"value":"depois","label":"Mais para frente"}]}]}'::jsonb, '[]'::jsonb, '{"required":true,"text":"Concordo em compartilhar meus dados para que a empresa entre em contato comigo sobre esta solicitação, conforme a política de privacidade."}'::jsonb, pg_temp.d(110), pg_temp.d(112));
  update public.lead_forms set current_published_version_id = 'e5e5e5e5-0000-4000-8000-00000000e003' where id = 'e5e5e5e5-0000-4000-8000-00000000f003';
  values ('e5e5e5e5-0000-4000-8000-00000000f004', org, 'Diagnóstico empresarial (rascunho)', 'diagnostico-empresarial', 'Segmento, faturamento, equipe, desafios e maturidade — para consultorias.', 'draft', 'Obrigado! Recebemos suas informações e entraremos em contato.', pg_temp.d(20));
  values ('e5e5e5e5-0000-4000-8000-00000000e004', org, 'e5e5e5e5-0000-4000-8000-00000000f004', 1, '{"steps":[{"id":"contato","title":"Seus dados"},{"id":"negocio","title":"O negócio"},{"id":"desafios","title":"Desafios"}],"fields":[{"key":"nome","type":"text","label":"Nome completo","required":true,"lead_field":"name","step":"contato"},{"key":"email","type":"email","label":"E-mail profissional","required":true,"lead_field":"email","step":"contato"},{"key":"telefone","type":"phone","label":"Telefone / WhatsApp","required":false,"lead_field":"phone","step":"contato"},{"key":"empresa","type":"text","label":"Empresa","required":true,"lead_field":"company_name","step":"contato"},{"key":"segmento","type":"select","label":"Segmento","required":true,"lead_field":"segment","step":"negocio","options":[{"value":"varejo","label":"Varejo"},{"value":"servicos","label":"Serviços"},{"value":"industria","label":"Indústria"},{"value":"saude","label":"Saúde"},{"value":"educacao","label":"Educação"},{"value":"outro","label":"Outro"}]},{"key":"faturamento","type":"select","label":"Faturamento anual","required":true,"step":"negocio","options":[{"value":"ate_500k","label":"Até R$ 500 mil"},{"value":"500k_3m","label":"R$ 500 mil a R$ 3 milhões"},{"value":"3m_20m","label":"R$ 3 a R$ 20 milhões"},{"value":"mais_20m","label":"Acima de R$ 20 milhões"}]},{"key":"equipe","type":"number","label":"Quantas pessoas na equipe?","required":true,"step":"negocio","min":1,"max":100000},{"key":"desafios","type":"multiselect","label":"Principais desafios","required":true,"step":"desafios","options":[{"value":"vendas","label":"Aumentar vendas"},{"value":"processos","label":"Organizar processos"},{"value":"custos","label":"Reduzir custos"},{"value":"pessoas","label":"Gestão de pessoas"},{"value":"tecnologia","label":"Tecnologia"}]},{"key":"maturidade","type":"radio","label":"Como os processos funcionam hoje?","required":true,"step":"desafios","options":[{"value":"informal","label":"De forma informal"},{"value":"parcial","label":"Parcialmente documentados"},{"value":"estruturado","label":"Estruturados e medidos"}]},{"key":"urgente","type":"checkbox","label":"Precisamos começar este mês","required":false,"step":"desafios"}]}'::jsonb, '[]'::jsonb, '{"required":true,"text":"Concordo em compartilhar meus dados para que a empresa entre em contato comigo sobre esta solicitação, conforme a política de privacidade."}'::jsonb, null, pg_temp.d(20));

  -- ---------------------------------------------------------------- modelo de score (regras sugeridas pelos modelos de formulário)
  update public.scoring_models set status = 'published', published_at = pg_temp.d(110) where id = model;


  -- ---------------------------------------------------------------- leads: respostas, notas (pelo motor do banco), histórico, atribuições e atividades
  for r in select * from seed_rows order by i loop
    v_form := case r.form_key when 'b2b' then 'e5e5e5e5-0000-4000-8000-00000000f001' when 'imobiliaria' then 'e5e5e5e5-0000-4000-8000-00000000f002' else 'e5e5e5e5-0000-4000-8000-00000000f003' end::uuid;
    v_ver := case r.form_key when 'b2b' then 'e5e5e5e5-0000-4000-8000-00000000e001' when 'imobiliaria' then 'e5e5e5e5-0000-4000-8000-00000000e002' else 'e5e5e5e5-0000-4000-8000-00000000e003' end::uuid;
    select schema_json, conditional_logic_json into v_schema, v_logic from public.lead_form_versions where id = v_ver;
    chk := public.lead_validate_answers(v_schema, v_logic, r.answers);
    v_rules := private.lead_rules_json(model, v_schema);
    res := public.lead_score_compute(v_rules, chk -> 'clean', v_thr, array(select jsonb_array_elements_text(chk -> 'hidden')));
    sc := (res ->> 'score')::int; cls := res ->> 'classification';
    select id into v_camp from public.campaigns where organization_id = org and campaign_key = r.campaign;
    v_lead := ('e5e5e5e5-1000-4000-8000-' || lpad(r.i::text, 12, '0'))::uuid;
    v_sub := ('e5e5e5e5-2000-4000-8000-' || lpad(r.i::text, 12, '0'))::uuid;
    v_created := pg_temp.d(r.created_ago, make_time(r.created_hour, (r.i * 7) % 60, 0));
    v_status := case r.plan when 'conv' then 'converted' when 'cont' then 'contacted' when 'qual' then 'qualifying' when 'disq' then 'disqualified' else 'new' end;
    v_assignee := case r.seller when 1 then u_v1 when 2 then u_v2 else null end;
    v_contact := case when r.plan in ('conv', 'cont') or (r.plan = 'qual' and r.i % 2 = 0) then v_created + r.contact_min * interval '1 minute' end;
    v_dup := case when r.dup_of is not null then ('e5e5e5e5-1000-4000-8000-' || lpad(r.dup_of::text, 12, '0'))::uuid end;

                              duplicate_of, needs_review, disqualify_reason, converted_at, first_contact_at, created_at, updated_at)
    values (v_lead, org, r.name, lower(r.email), '55' || regexp_replace(r.phone, '\D', '', 'g'), r.company, r.segment, v_status, cls, (res ->> 'qualified')::boolean, sc, v_assignee,
            case when r.source = 'direto' then null else r.source end, r.medium, v_camp, v_form, v_dup, v_dup is not null, case when r.plan = 'disq' then r.reason end,
            case when r.plan = 'conv' then v_contact + interval '2 days' end, v_contact, v_created, v_created);
    values (v_sub, org, v_form, v_ver, v_lead, chk -> 'clean', true, v_dup is not null, case when r.source = 'direto' then 'direto' else r.source end,
            case when r.source = 'direto' then null else r.source end, r.medium, r.campaign, 'https://exemplo-demo.invalid/f/' || r.form_key, v_created);
    values (org, v_lead, model, v_sub, sc, cls, (res ->> 'qualified')::boolean, res || jsonb_build_object('model_version', 1, 'model_name', 'Modelo de qualificação comercial'), v_created);

    -- histórico de status
    if r.plan in ('qual', 'cont', 'conv') then
    end if;
    if r.plan in ('cont', 'conv') then
    end if;
    if r.plan = 'conv' then
    end if;
    if r.plan = 'disq' then
    end if;
    -- atribuição (rodízio)
    if v_assignee is not null then
    end if;
    -- atividades: primeiro contato concluído; follow-up agendado (alguns vencidos)
    if v_contact is not null then
      values (org, v_lead, v_assignee, (case when r.i % 3 = 0 then 'message' when r.i % 3 = 1 then 'call' else 'email' end)::public.lead_activity_type, 'Primeiro contato realizado.', v_contact, v_contact);
    end if;
    if r.plan in ('cont', 'qual') and r.i % 2 = 1 then
      values (org, v_lead, v_assignee, 'call'::public.lead_activity_type, 'Retornar a ligação e confirmar a proposta.', pg_temp.d(-r.follow_days, '10:00'), coalesce(v_contact, v_created));
    end if;
  end loop;

  -- uma análise de IA de exemplo (a IA segue desabilitada; este registro só mostra como a sugestão aparece, separada do score)
  select org, id, 'demonstracao', 'exemplo', jsonb_build_object('summary', 'Lead com bom encaixe: orçamento compatível e prazo curto. Vale priorizar o contato.',
         'strengths', jsonb_build_array('Prazo de decisão curto', 'Orçamento compatível'), 'risks', jsonb_build_array('Pouco detalhe sobre o problema a resolver'), 'next_steps', jsonb_build_array('Ligar hoje', 'Enviar proposta preliminar')), 'ok', pg_temp.d(2)
  from public.leads where organization_id = org and qualification = 'hot' and status = 'contacted' order by created_at desc limit 1;

  perform pg_temp.triggers(true);
end $$;
